def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    direction = 'RIGHT'
    if direction == 'RIGHT':
        old_char = board[row][col]
        new_char = 'W' if old_char == 'S' else 'S'
        board[row][col] = new_char

        # Move right
        for i in range(col+1, 64):
            if board[row][i] == 'S':
                board[row][i] = 'W'
            elif board[row][i] == 'W':
                board[row][i] = 'S'

        # Move down
        for i in range(row+1, 64):
            if board[i][col] == 'S':
                board[i][col] = 'W'
            elif board[i][col] == 'W':
                board[i][col] = 'S'

    return ["".join(row) for row in board]
